import {total} from './cost.mjs';
const form=document.querySelector('#compare');
if(form){const output=document.querySelector('#result');function update(){const data=new FormData(form);if(!data.get('a-price')||!data.get('b-price')){output.textContent='2つの候補の商品価格を入力すると、支払額の差が分かります。';return;}try{const values=['a','b'].map(k=>total(Object.fromEntries(['price','shipping','coupon'].map(x=>[x,Number(data.get(`${k}-${x}`))]))));const diff=Math.abs(values[0]-values[1]);output.textContent=`候補A：${values[0].toLocaleString('ja-JP')}円 ／ 候補B：${values[1].toLocaleString('ja-JP')}円。${diff?`支払額は候補${values[0]<values[1]?'A':'B'}が${diff.toLocaleString('ja-JP')}円低くなります。`:'支払額は同じです。'} ポイント還元は差し引いていません。`;}catch(e){output.textContent=e.message;}}form.addEventListener('input',update);form.addEventListener('reset',()=>setTimeout(update,0));update();}
